  'stuSess.refundSuccessStripeNote': '<p class="text-emerald-900 text-sm mb-2">Pytania lub problemy? Skontaktuj się z <a href="mailto:info@tutlio.lt" class="underline font-medium">info@tutlio.lt</a>.</p><p class="font-semibold text-emerald-900">Twój zwrot został uruchomiony przez Stripe.</p><p class="text-emerald-800 mt-1">Zwroty na kartę zwykle docierają w ciągu <strong>5–10 dni roboczych</strong> (banki mogą się różnić). Jeśli nie otrzymasz go w zwykłym terminie, napisz na <a href="mailto:info@tutlio.lt" class="text-emerald-900 underline font-medium">info@tutlio.lt</a>.</p>',
  'stuSess.refundSuccessManualTutor': '<p>Ta lekcja nie wygląda na opłaconą przez Tutlio Stripe (np. przelew bankowy lub gotówka). Automatyczny zwrot nie jest tutaj dostępny.</p><p class="mt-2">Aby ustalić zwrot, skontaktuj się z korepetytorem <strong>{tutor}</strong> — użyj e-maila lub danych z rezerwacji.</p>',
  'stuSess.refundSuccessManualOrg': '<p>Ta lekcja nie wygląda na opłaconą przez Tutlio Stripe (np. przelew bankowy lub gotówka). Automatyczny zwrot nie jest tutaj dostępny.</p><p class="mt-2">Ponieważ uczysz się przez organizację, skontaktuj się z <strong>administratorem organizacji</strong> (przez korepetytora lub opublikowane kontakty organizacji).</p>',
