  // --- priv (Privacy Policy) ---

  // --- tos (Terms of Service) ---

  'orgTutorPolicy.title': 'Zasady wewnętrzne dla korepetytorów',
  'orgTutorPolicy.intro': 'Przed rozpoczęciem korzystania z platformy zapoznaj się z wewnętrznymi zasadami organizacji.',
  'orgTutorPolicy.acceptBtn': 'Rozumiem',
  'orgTutorPolicy.viewBtn': 'Zobacz zasady wewnętrzne',
  'orgTutorPolicy.s1Title': '1. Postanowienia ogólne',
  'orgTutorPolicy.s1Body': 'Niniejsze zasady regulują korzystanie z platformy Tutlio („Platforma”) przez Ciebie jako nauczyciela lub korepetytora („Korepetytor”). Zostałeś zaproszony do korzystania z Platformy przez agencję edukacyjną, szkołę lub centrum korepetycji, które reprezentujesz („Organizacja”). Platforma jest technicznie utrzymywana i wspierana przez MB Tutlio. Korzystając ze swojego konta, akceptujesz niniejsze Zasady oraz Politykę Prywatności.',
  'orgTutorPolicy.s2Title': '2. Zarządzanie kontem i harmonogramem',
  'orgTutorPolicy.s2Intro': 'Platforma została zaprojektowana tak, abyś nie musiał tracić czasu na uzgadnianie terminów lekcji z uczniami.',
  'orgTutorPolicy.s2Link': 'Unikalny link: Otrzymujesz osobisty link do rezerwacji lekcji (według przedmiotów, których uczysz), z którego uczniowie korzystają przy umawianiu zajęć.',
  'orgTutorPolicy.s2Calendar': 'Synchronizacja kalendarza: Twoja dostępność zależy bezpośrednio od integracji z Google Calendar (synchronizacja dwukierunkowa). Jesteś osobiście odpowiedzialny za to, aby wolny czas widoczny w Twoim kalendarzu był aktualny i prawidłowy. Platforma nie pozwoli uczniom zarezerwować terminów oznaczonych w Twoim kalendarzu jako zajęte.',
  'orgTutorPolicy.s2Security': 'Bezpieczeństwo konta: Twoje konto jest osobiste. Musisz chronić swoje dane logowania i nie udostępniać ich osobom trzecim.',
  'orgTutorPolicy.s3Title': '3. Odwoływanie lekcji i lista oczekujących',
  'orgTutorPolicy.s3Intro': 'Platforma pomaga maksymalnie wypełnić Twój harmonogram i uniknąć pustych okienek:',
  'orgTutorPolicy.s3Auto': 'Jeśli uczeń odwoła lekcję, Platforma automatycznie wysyła powiadomienie (SMS/e-mail) do innych uczniów na Twojej liście oczekujących, proponując wolny termin. Nie musisz podejmować żadnych dodatkowych działań.',
  'orgTutorPolicy.s3Rules': 'Zasady odwoływania lekcji (z jakim wyprzedzeniem można odwołać, jakie są konsekwencje) ustala Twoja Organizacja.',
  'orgTutorPolicy.s4Title': '4. Finanse i rozliczenia',
  'orgTutorPolicy.s4Intro': 'Nie musisz się martwić wystawianiem faktur ani pobieraniem płatności od rodziców:',
  'orgTutorPolicy.s4Advance': 'Wszystkie płatności uczniów (lub rodziców) za Twoje lekcje są pobierane z góry przez Platformę i przekazywane bezpośrednio Twojej Organizacji.',
  'orgTutorPolicy.s4Confirmed': 'Prowadzisz lekcję dopiero wtedy, gdy jest ona potwierdzona w systemie (co oznacza, że opłata już została pobrana).',
  'orgTutorPolicy.s4Contact': 'W sprawach wynagrodzenia, harmonogramu wypłat i innych kwestii finansowych skontaktuj się bezpośrednio z administratorem swojej Organizacji. MB Tutlio nie prowadzi żadnych bezpośrednich rozliczeń finansowych z Korepetytorami.',
  'orgTutorPolicy.s5Title': '5. Ochrona danych uczniów (RODO)',
  'orgTutorPolicy.s5Intro': 'Jako Korepetytor masz dostęp do danych osobowych uczniów, wewnętrznych notatek i materiałów edukacyjnych. Zobowiązujesz się do:',
  'orgTutorPolicy.s5Use': 'Wykorzystywania tych danych wyłącznie do organizowania i prowadzenia lekcji.',
  'orgTutorPolicy.s5NoCopy': 'Niekopiowania, nieeksportowania i nierozpowszechniania danych kontaktowych uczniów lub ich rodziców poza Platformą.',
  'orgTutorPolicy.s5Notes': 'Ochrony wewnętrznych zapisów Organizacji (notatek o postępach ucznia), które są widoczne tylko dla Ciebie i administracji Organizacji, a nie dla uczniów ani rodziców.',
  'orgTutorPolicy.s5Termination': 'Po zakończeniu współpracy z Organizacją Twój dostęp do tych danych zostanie natychmiast cofnięty.',
  'orgTutorPolicy.s6Title': '6. Działanie techniczne i ograniczenie odpowiedzialności',
  'orgTutorPolicy.s6Body': 'Wykorzystywanie Platformy do celów niezgodnych z prawem, rozpowszechnianie złośliwych linków w materiałach lekcyjnych lub inne zakłócanie pracy systemu jest zabronione. MB Tutlio zapewnia działanie i obsługę techniczną Platformy, lecz nie ponosi odpowiedzialności za zakłócenia spowodowane Twoim połączeniem internetowym, awariami sprzętu lub nieprawidłowymi ustawieniami Google Calendar.',
  'orgTutorPolicy.s7Title': '7. Pomoc i kontakt',
  'orgTutorPolicy.s7Org': 'W razie pytań dotyczących harmonogramu lekcji, wynagrodzenia, przydziału uczniów lub organizacji pracy skontaktuj się z administratorem swojej Organizacji.',
  'orgTutorPolicy.s7Tech': 'W przypadku błędów technicznych Platformy (synchronizacja kalendarza nie działa, brak powiadomień) poinformuj administratora Organizacji, który skontaktuje się z zespołem wsparcia technicznego Tutlio.',

