  'feature.cancellation.pageTitle': 'Zasady anulowania i opłaty za późne anulowanie dla korepetytorów',
  'feature.cancellation.pageDesc': 'Ustal jasne terminy anulowania i automatyczne opłaty za późne anulowanie. Gdy uczniowie anulują, zwolnione terminy trafiają od razu na Twoją listę oczekujących.',
  'feature.cancellation.detailsTitle': 'Jak działają zasady anulowania',
  'feature.cancellation.deadlines': 'Terminy anulowania',
  'feature.cancellation.deadlinesDesc': 'Określ, z jakim wyprzedzeniem uczniowie muszą anulować (np. 24 godziny przed lekcją), aby uniknąć opłaty za anulowanie.',
  'feature.cancellation.fees': 'Automatyczne opłaty za późne anulowanie',
  'feature.cancellation.feesDesc': 'Ustaw opłatę procentową (np. 50% ceny lekcji), która jest automatycznie naliczana, gdy uczeń anuluje zbyt późno.',
  'feature.cancellation.transparency': 'Jasna komunikacja z uczniami',
  'feature.cancellation.transparencyDesc': 'Uczniowie widzą Twoje zasady anulowania od razu podczas rezerwacji. Żadnych niespodzianek — tylko profesjonalne, uczciwe zasady.',
  'feature.cancellation.waitlistLink': 'Integracja z listą oczekujących',
  'feature.cancellation.waitlistLinkDesc': 'Anulowane terminy są natychmiast oferowane uczniom z listy oczekujących, dzięki czemu Twój grafik pozostaje pełny, a przychód chroniony.',
  'feature.cancellation.faq.howSetQ': 'Jak ustawić zasady anulowania?',
  'feature.cancellation.faq.howSetA': 'Przejdź do ustawień lekcji i określ termin anulowania (godziny przed lekcją) oraz procent opłaty za późne anulowanie. System egzekwuje je automatycznie.',
  'feature.cancellation.faq.refundQ': 'Co dzieje się z opłatą za anulowanie?',
  'feature.cancellation.faq.refundA': 'Opłaty za późne anulowanie są automatycznie obliczane i dodawane do salda ucznia. Wszystkie opłaty możesz śledzić w panelu finansowym.',
  'feature.cancellation.faq.studentSeeQ': 'Czy uczniowie widzą zasady anulowania?',
  'feature.cancellation.faq.studentSeeA': 'Tak, Twoje warunki anulowania są pokazywane uczniom podczas rezerwacji, aby znali zasady przed potwierdzeniem.',
  'feature.comments.pageTitle': 'Notatki z lekcji, komentarze i udostępnianie plików dla korepetytorów',
  'feature.comments.pageDesc': 'Dołączaj notatki, prace domowe i pliki do poszczególnych lekcji. Twórz pełną historię lekcji dostępną dla uczniów i rodziców w każdej chwili.',
  'feature.comments.detailsTitle': 'Jak działają notatki z lekcji',
  'feature.comments.lessonNotes': 'Notatki do każdej lekcji',
  'feature.comments.lessonNotesDesc': 'Dodawaj prywatne lub udostępnione notatki do dowolnej lekcji — śledź, co zostało omówione, postępy ucznia i kolejne kroki.',
  'feature.comments.fileSharing': 'Załączniki plików',
  'feature.comments.fileSharingDesc': 'Przesyłaj karty pracy, prace domowe w PDF lub materiały do nauki i dołączaj je bezpośrednio do lekcji dla łatwego dostępu.',
  'feature.comments.history': 'Pełna historia lekcji',
  'feature.comments.historyDesc': 'Każda notatka i plik są powiązane z lekcją, do której należą, tworząc przeszukiwalną oś czasu nauki każdego ucznia.',
  'feature.comments.parentAccess': 'Widoczność dla rodziców',
  'feature.comments.parentAccessDesc': 'Rodzice mogą zobaczyć udostępnione notatki z lekcji i pliki w swoim portalu, dzięki czemu są na bieżąco z postępami dziecka.',
  'feature.comments.faq.whoSeesQ': 'Kto może zobaczyć notatki z lekcji?',
  'feature.comments.faq.whoSeesA': 'Ty decydujesz, co udostępnić. Notatki mogą być prywatne (tylko dla korepetytora) lub udostępnione uczniowi i jego rodzicowi.',
  'feature.comments.faq.fileTypesQ': 'Jakie typy plików mogę przesłać?',
  'feature.comments.faq.fileTypesA': 'Możesz przesyłać pliki PDF, obrazy i popularne formaty dokumentów. Pliki są bezpiecznie przechowywane i dostępne z dowolnego urządzenia.',
  'feature.comments.faq.storageQ': 'Czy istnieje limit przechowywania?',
  'feature.comments.faq.storageA': 'Wszystkie plany obejmują pojemną przestrzeń na pliki. Nie ma limitów na pojedynczy plik — dołączaj tyle materiałów, ile potrzebujesz.',
  'noShow.title': 'Uczeń się nie stawił',
  'noShow.desc': 'Lekcja zostanie oznaczona jako <strong class="text-foreground">nieodbyta</strong>. Do komentarza dodamy krótki standardowy tekst (przed / w trakcie / po lekcji) w zależności od momentu <strong class="text-foreground">potwierdzenia</strong> oraz zaplanowanego początku i końca lekcji.',
