  'featuresIndex.subtitle': 'Od harmonogramu lekcji i listy oczekujących po płatności Stripe, faktury i portal dla rodziców — kompletna platforma do zarządzania korepetycjami w jednym miejscu.',
  'featuresIndex.metaDesc': 'Funkcje Tutlio: inteligentny kalendarz, lista oczekujących, płatności Stripe, przypomnienia, zasady odwoływania, wiadomości, pakiety i więcej dla firm korepetytorskich.',
  'featuresIndex.deepTitle': 'Szczegółowe opisy funkcji',
  'featuresIndex.deepSubtitle': 'Dowiedz się, jak każda funkcja oszczędza czas i pomaga rozwijać biznes korepetytorski.',
  'featuresIndex.allTitle': 'Wszystko, co zawiera Tutlio',
  'featuresIndex.allSubtitle': 'Wszystkie funkcje są dostępne w każdym planie — bez ukrytych dodatków i opłat za funkcje.',
  'featuresIndex.readMore': 'Czytaj więcej',
  'schoolsLanding.faq.whatIsQ': 'Czym jest Tutlio dla szkół?',
  'schoolsLanding.faq.whatIsA': 'Tutlio Schools to oprogramowanie do zarządzania szkołą korepetycji — harmonogram nauczycieli, CRM uczniów, umowy, płatności i raporty na jednej platformie.',
  'schoolsLanding.faq.whoForQ': 'Dla kogo jest Tutlio Schools?',
  'schoolsLanding.faq.whoForA': 'Dla szkół językowych, centrów korepetycji, szkół muzycznych, programów przygotowania do egzaminów i każdej organizacji zarządzającej wieloma korepetytorami i uczniami.',
  'schoolsLanding.faq.contractsQ': 'Czy możemy zarządzać umowami i płatnościami?',
  'schoolsLanding.faq.contractsA': 'Tak. Platforma obsługuje szablony umów, podpis elektroniczny, plany ratalne, płatności Stripe i raportowanie finansowe.',
  'schoolsLanding.faq.pricingQ': 'Jak działa cennik dla szkół?',
  'schoolsLanding.faq.pricingA': 'Szkoły otrzymują indywidualny cennik zależny od liczby korepetytorów i potrzeb. Skontaktuj się z nami po ofertę.',
  'schoolsLanding.faq.trialQ': 'Czy można przetestować przed zakupem?',
  'schoolsLanding.faq.trialA': 'Tak — umów się na bezpłatną konsultację i demo. Pokażemy, jak Tutlio pasuje do pracy Twojej szkoły.',
