  'em.packageHowBodyProKlase': 'Kupując pakiet lekcji, opłacasz wszystkie lekcje zaplanowane na bieżący miesiąc. Jeśli nie możesz uczestniczyć w opłaconej lekcji, możesz ją przełożyć, uzgadniając wcześniej nowy termin z korepetytorem.<br/><br/>Jeśli chcesz umówić dodatkowe lekcje w ciągu miesiąca, możesz opłacić je osobno.',
