  'landing.v2.businessCardCta': 'Zobacz, jak to działa',
  'landing.feature.digital-business-card': 'Cyfrowa wizytówka',
  'landing.feature.digital-business-cardDesc': 'Udostępnij jedną profesjonalną stronę, na której uczniowie poznają Cię, zobaczą aktualne ceny i wolne terminy oraz od razu wyślą zgłoszenie na lekcję.',
  'featuresIndex.newBadge': 'Nowość',
  'feature.digital-business-card.pageTitle': 'Cyfrowa wizytówka, która zamienia zainteresowanie w zgłoszenia na lekcje',
  'feature.digital-business-card.pageDesc': 'Daj każdemu potencjalnemu uczniowi jeden dopracowany link z Twoim opisem, lekcjami, cenami, opiniami i aktualnymi wolnymi terminami. Uczeń od razu wybiera lekcję i godzinę, a Ty nie tracisz zgłoszeń w długich rozmowach.',
  'feature.digital-business-card.detailsTitle': 'Wszystko, czego potencjalny uczeń potrzebuje, aby powiedzieć „tak”',
  'feature.digital-business-card.oneLink': 'Jeden link do całej Twojej działalności korepetytorskiej',
  'feature.digital-business-card.oneLinkDesc': 'Zastąp rozproszone profile społecznościowe, cenniki i wiadomości o rezerwacjach jedną stroną, którą możesz udostępniać wszędzie.',
  'feature.digital-business-card.liveAvailability': 'Zawsze aktualne wolne terminy',
  'feature.digital-business-card.liveAvailabilityDesc': 'Wolne godziny pochodzą bezpośrednio z Twojego kalendarza Tutlio, więc klienci wybierają tylko terminy, w których naprawdę chcesz uczyć.',
  'feature.digital-business-card.instantEnquiries': 'Zgłoszenia na lekcje, gdy Ty uczysz',
  'feature.digital-business-card.instantEnquiriesDesc': 'Rodzic lub uczeń wybiera lekcję, formę i termin, a następnie zostawia dane. Otrzymujesz kompletne zgłoszenie bez ustalania godziny w wiadomościach.',
  'feature.digital-business-card.professionalBrand': 'Profesjonalne pierwsze wrażenie',
  'feature.digital-business-card.professionalBrandDesc': 'Pokaż zdjęcie, sposób nauczania, przedmioty, ceny, zweryfikowane opinie i kolory marki na stronie, która świetnie działa na każdym telefonie.',
  'feature.digital-business-card.faq.whatShowsQ': 'Co mogę pokazać na cyfrowej wizytówce?',
  'feature.digital-business-card.faq.whatShowsA': 'Możesz przedstawić siebie, przedmioty, formy lekcji, publiczne ceny, wolne terminy w kalendarzu, lokalizację, języki, linki społecznościowe i zweryfikowane opinie uczniów.',
  'feature.digital-business-card.faq.howBookingWorksQ': 'Czy klient od razu rezerwuje potwierdzoną lekcję?',
  'feature.digital-business-card.faq.howBookingWorksA': 'Klient wybiera lekcję i dostępny termin, a potem wysyła kompletne zgłoszenie rezerwacji. Otrzymujesz je w Tutlio i możesz zaakceptować nowego ucznia, zanim lekcja trafi do grafiku.',
  'feature.digital-business-card.faq.whereShareQ': 'Gdzie najlepiej udostępniać tę stronę?',
  'feature.digital-business-card.faq.whereShareA': 'Dodaj ją na Instagramie, TikToku, w grupach na Facebooku, reklamach, podpisie e-mail, wiadomościach i kodach QR. Jeden link pozostaje aktualny nawet po zmianie cen lub kalendarza.',
